import React, { useState, useEffect } from "react";
import axios from "axios";
import { API } from "../config";

function AdminPanel({ token }) {
  const [challans, setChallans] = useState([]);
  const [form, setForm] = useState({});
  const [stats, setStats] = useState({});

  useEffect(() => {
    fetchAll();
  }, []);

  const fetchAll = async () => {
    try {
      const res = await axios.get(`${API}/challan/all`);
      setChallans(res.data.challans);
      setStats({ total: res.data.total, paid: res.data.paid, pending: res.data.pending });
    } catch (err) {
      console.error(err);
    }
  };

  const addChallan = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`${API}/challan/add`, form, { headers: { Authorization: token } });
      alert("Challan added");
      fetchAll();
    } catch (err) {
      console.error(err);
      alert("Error adding challan");
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>Admin Panel</h2>
      <p>Total: {stats.total} | Paid: {stats.paid} | Pending: {stats.pending}</p>

      <h3>Add Challan</h3>
      <form onSubmit={addChallan}>
        <input placeholder="Vehicle Number" onChange={(e) => setForm({ ...form, vehicleNumber: e.target.value })} /><br />
        <input placeholder="Cause" onChange={(e) => setForm({ ...form, cause: e.target.value })} /><br />
        <input placeholder="Fine" onChange={(e) => setForm({ ...form, fine: e.target.value })} /><br />
        <input placeholder="Address" onChange={(e) => setForm({ ...form, address: e.target.value })} /><br />
        <input placeholder="Issue Date YYYY-MM-DD" onChange={(e) => setForm({ ...form, issueDate: e.target.value })} /><br />
        <input placeholder="Due Date YYYY-MM-DD" onChange={(e) => setForm({ ...form, dueDate: e.target.value })} /><br />
        <button type="submit">Add Challan</button>
      </form>

      <h3>All Challans</h3>
      <table border="1" cellPadding="6">
        <thead>
          <tr>
            <th>#</th>
            <th>Vehicle</th>
            <th>Cause</th>
            <th>Fine</th>
            <th>Status</th>
            <th>Issue</th>
            <th>Due</th>
            <th>Address</th>
          </tr>
        </thead>
        <tbody>
          {challans.map((c, i) => (
            <tr key={c._id}>
              <td>{i + 1}</td>
              <td>{c.vehicleNumber}</td>
              <td>{c.cause}</td>
              <td>{c.fine}</td>
              <td>{c.status}</td>
              <td>{c.issueDate}</td>
              <td>{c.dueDate}</td>
              <td>{c.address}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default AdminPanel;
